33	    [data-color="cyan"] { --fg: #0891b2; }
34	    @media (prefers-color-scheme: dark) {
35	      :root {
36	        --bg: #111;
37	        --text: #d1d5db;
38	        --fg: #93c5fd;
39	        --shadow: rgba(0, 0, 0, 0.6);
40	        --kbd-bg: rgba(255, 255, 255, 0.15);
41	      }
42	      [data-color="red"] { --fg: #fca5a5; }
43	      [data-color="green"] { --fg: #86efac; }
44	      [data-color="amber"] { --fg: #fcd34d; }
45	      [data-color="violet"] { --fg: #c4b5fd; }
46	      [data-color="cyan"] { --fg: #67e8f9; }
47	    }
48	    @media (prefers-contrast: more) {
49	      :root {
50	        --shadow: rgba(0, 0, 0, 0.9);
51	        --drop: drop-shadow(0 2px 8px var(--shadow));
52	      }
53	      .hint {
54	        opacity: 1 !important;
55	      }
56	    }
57	    @media (forced-colors: active) {
58	      svg circle {
59	        stroke: CanvasText;
60	        stroke-width: 2;
61	      }
62	    }
63	    body {
64	      min-height: 100vh;
65	      min-height: 100dvh;
66	      display: grid;
67	      place-items: center;
68	      padding: 1rem;
69	      background: var(--bg);
70	      color: var(--text);
71	      font-family: system-ui, -apple-system, sans-serif;
72	    }
73	    main {
74	      width: 100%;
75	      display: flex;
76	      flex-direction: column;
77	      align-items: center;
78	      text-align: center;
79	    }
80	    button {
81	      display: block;
82	      width: min(360px, 100%, 60vh);
83	      aspect-ratio: 1;
84	      border: 0;
85	      border-radius: 50%;
86	      background: none;
87	      color: var(--fg);
88	      cursor: pointer;
89	      touch-action: manipulation;
90	      -webkit-tap-highlight-color: transparent;
91	      transition: color 0.4s ease;
92	      position: relative;
93	      min-height: 48px;
94	      min-width: 48px;
95	    }
96	    .color-indicator {
97	      position: absolute;
98	      bottom: 12%;
99	      right: 12%;
100	      width: 1rem;
101	      height: 1rem;
102	      border-radius: 50%;
103	      background: currentColor;
104	      border: 2px solid var(--bg);
105	      box-shadow: 0 2px 4px var(--shadow);
106	    }
107	    .no-transition,
108	    .no-transition svg,
109	    .no-transition .color-indicator {
110	      transition: none !important;
111	    }
112	    button:focus-visible {
113	      outline: 3px solid currentColor;
114	      /* Must clear the scaled-up circle (up to 9px) or the ring merges with it */
115	      outline-offset: 12px;
116	    }
117	    svg {
118	      display: block;
119	      width: 100%;
120	      height: 100%;
121	      overflow: visible;
122	      opacity: 0.85;
123	      filter: var(--drop);
124	      transition: opacity 0.3s ease;
125	    }
126	    button:active svg,
127	    button:focus-visible svg {
128	      opacity: 1;
129	    }
130	    @keyframes pulse {
131	      0% {
132	        filter: var(--drop) drop-shadow(0 0 16px currentColor);
133	      }
134	      100% {
135	        filter: var(--drop) drop-shadow(0 0 0 transparent);
136	      }
137	    }
138	    @media (hover: hover) {
139	      button:hover svg {
140	        opacity: 1;
141	      }
142	    }
143	    @media (prefers-reduced-motion: no-preference) {
144	      svg {
145	        transition:
146	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
147	          opacity 0.3s ease;
148	      }
149	      button:focus-visible svg {
150	        transform: scale(1.05);
151	      }
152	      button:active svg {
153	        transform: scale(0.97);
154	      }
155	      button.color-changed svg {
156	        animation: pulse 0.5s ease-out;
157	      }
158	    }
159	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
160	      button:hover:not(:active) svg {
161	        transform: scale(1.05);
162	      }
163	    }
164	    .visually-hidden {
165	      position: absolute;
166	      width: 1px;
167	      height: 1px;
168	      overflow: hidden;
169	      clip-path: inset(50%);
170	      white-space: nowrap;
171	    }
172	    .status {
173	      margin-top: 2rem;
174	      font-weight: 600;
175	    }
176	    .hint {
177	      margin-top: 0.25rem;
178	      font-size: 0.875rem;
179	      opacity: 0.8;
180	    }
181	    @media (hover: none) and (pointer: coarse) {
182	      .hint .keys {
183	        display: none;
184	      }
185	    }
186	    kbd {
187	      display: inline-block;
188	      padding: 0.125rem 0.375rem;
189	      background: var(--kbd-bg);
190	      border: 1px solid transparent;
191	      border-radius: 0.25rem;
192	      font-family: monospace;
193	      font-size: 0.75em;
194	    }
195	  </style>
196	</head>
197	<body>
198	  <main>
199	    <h1 class="visually-hidden">Animated Circle</h1>
200	    <button type="button" class="no-transition" aria-label="Change circle color" aria-describedby="status hint">
201	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
202	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
203	      </svg>
204	      <span class="color-indicator" aria-hidden="true"></span>
205	    </button>
206	    <p class="status" id="status" role="status" aria-atomic="true" aria-live="polite">Blue</p>
207	    <p class="hint" id="hint"><span class="verb">Click</span> to cycle<span class="keys"> • <kbd>Shift</kbd>+click reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></p>
208	  </main>
209	  <script>
210	    const button = document.querySelector('button');
211	    const status = document.querySelector('.status');
212	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
213	    const storageKey = 'circle-color';
214	    const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
215	
216	    // Safely retrieve saved color from localStorage, returning null if unavailable
217	    function loadColor() {
218	      try {
219	        return localStorage.getItem(storageKey);
220	      } catch {
221	        return null;
222	      }
223	    }
224	
225	    // Safely save color to localStorage, silently failing if unavailable
226	    function saveColor(color) {
227	      try {
228	        localStorage.setItem(storageKey, color);
229	      } catch {}
230	    }
231	
232	    const savedColor = loadColor();
233	    let index = colors.includes(savedColor) ? colors.indexOf(savedColor) : 0;
234	
235	    // Apply current color to button and update status display
236	    function applyColor() {
237	      const color = colors[index];
238	      if (color === 'blue') {
239	        delete button.dataset.color;
240	      } else {
241	        button.dataset.color = color;
242	      }
243	      status.textContent = color[0].toUpperCase() + color.slice(1);
244	    }
245	
246	    // Cycle color by step amount and trigger pulse animation
247	    function changeColor(step) {
248	      const next = (index + step + colors.length) % colors.length;
249	      // Home/End at the boundary shouldn't pulse or rewrite storage
250	      if (next === index) return;
251	      index = next;
252	      applyColor();
253	      saveColor(colors[index]);
254	
255	      // Haptic feedback for supported devices
256	      if (navigator.vibrate) navigator.vibrate(50);
257	
258	      // With reduced motion no animation runs, so animationend would never clear the class
259	      if (reducedMotion.matches) return;
260	      button.classList.remove('color-changed');
261	      void button.offsetWidth;
262	      button.classList.add('color-changed');
263	    }
264	
265	    applyColor();
266	    // Double rAF ensures paint completes before enabling animations
267	    requestAnimationFrame(() => requestAnimationFrame(() => {
268	      button.classList.remove('no-transition');
269	    }));
270	
271	    // Update instructions to show "Tap" on touch devices or "Click" on hover-capable devices
272	    const hoverQuery = matchMedia('(hover: none)');
273	    const verbSpan = document.querySelector('.hint .verb');
274	    function updateVerb() {
275	      verbSpan.textContent = hoverQuery.matches ? 'Tap' : 'Click';
276	    }
277	    updateVerb();
278	    hoverQuery.addEventListener('change', updateVerb);
279	
280	    // Space and Enter activate through the native click, but keyboard-synthesized
281	    // clicks don't reliably carry shiftKey, so remember it from the key events
282	    let shiftHeld = false;
283	    const isActivationKey = (event) => event.key === 'Enter' || event.key === ' ';
284	    // Space clicks on keyup; Enter already clicked on keydown, so updating
285	    // shiftHeld on Enter's keyup would leak into the next mouse click
286	    button.addEventListener('keyup', (event) => {
287	      if (event.key === ' ') shiftHeld = event.shiftKey;
288	    });
289	    button.addEventListener('blur', () => {
290	      shiftHeld = false;
291	    });
292	
293	    const keySteps = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
294	    button.addEventListener('keydown', (event) => {
295	      if (isActivationKey(event)) {
296	        // Holding Enter would otherwise fire a click on every repeat; no click
297	        // follows to reset shiftHeld, so setting it here would leak into the
298	        // next mouse click
299	        if (event.repeat) {
300	          if (event.key === 'Enter') event.preventDefault();
301	          return;
302	        }
303	        shiftHeld = event.shiftKey;
304	        return;
305	      }
306	      if (event.altKey || event.ctrlKey || event.metaKey) return;
307	      if (event.key in keySteps) {
308	        event.preventDefault();
309	        changeColor(keySteps[event.key]);
310	      } else if (event.key === 'Home') {
311	        event.preventDefault();
312	        changeColor(-index);
313	      } else if (event.key === 'End') {
314	        event.preventDefault();
315	        changeColor(colors.length - 1 - index);
316	      }
317	    });
318	    button.addEventListener('click', (event) => {
319	      changeColor(event.shiftKey || shiftHeld ? -1 : 1);
320	      shiftHeld = false;
321	    });
322	    button.addEventListener('animationend', () => {
323	      button.classList.remove('color-changed');
324	    });
325	    // Sync color across tabs when storage changes
326	    addEventListener('storage', (event) => {
327	      // key is null when another tab calls localStorage.clear()
328	      if (event.key !== storageKey && event.key !== null) return;
329	      const newIndex = colors.indexOf(event.newValue);
330	      index = newIndex === -1 ? 0 : newIndex;
331	      applyColor();
332	    });
333	  </script>
334	</body>
335	</html>
