// Apply current color to button and update status display
function applyColor() {
  const color = colors[index];
  if (color === 'blue') {
    delete button.dataset.color;
  } else {
    button.dataset.color = color;
  }
  const displayName = color[0].toUpperCase() + color.slice(1);
  const hexCode = colorHex[color];
  status.textContent = displayName;
  button.setAttribute('aria-label', `Change circle color (currently ${displayName} ${hexCode})`);
}

// Cycle color by step amount and trigger pulse animation
function changeColor(step) {
  const next = (index + step + colors.length) % colors.length;
  // Home/End at the boundary shouldn't pulse or rewrite storage
  if (next === index) return;
  index = next;
  applyColor();
  saveColor(colors[index]);

  // Haptic feedback for supported devices
  if (navigator.vibrate) navigator.vibrate(50);

  // With reduced motion no animation runs, so animationend would never clear the class
  if (reducedMotion.matches) return;
  button.classList.remove('color-changed');
  void button.offsetWidth;
  button.classList.add('color-changed');
}

applyColor();
